def solve(nums, k):
    def dfs(path, start, count):
        if count == k:
            return path[-1]
        for i in range(start, len(nums)):
            if nums[i] not in path:
                path.append(nums[i])
                res = dfs(path, i + 1, count + 1)
                if res is not None:
                    return res
                path.pop()
        return None

    return dfs([], 0, 0)

