def solve(nums):
    def length_of_lis(nums, memo):
        if not nums:
            return 0
        if len(nums) in memo:
            return memo[len(nums)]
        max_len = 1
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[j] > nums[i]:
                    current = 1 + length_of_lis(nums[j:], memo)
                    max_len = max(max_len, current)
        memo[len(nums)] = max_len
        return max_len

    memo = {}
    return length_of_lis(nums, memo)

