    def get_components_count(n, edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        visited = [False] * n
        components = 0

        for node in range(n):
            if not visited[node]:
                components += 1
                stack = [node]
                visited[node] = True
                while stack:
                    current = stack.pop()
                    for neighbor in graph[current]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        return components

    return get_components_count(n, edges)

