        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    parent = list(range(n))
    rank = [1] * n

    for u, v in edges:
        union(parent, rank, u, v)

    roots = set()
    for i in range(n):
        roots.add(find(parent, i))

    return len(roots)

