def solve(edges, num_nodes):
    from collections import defaultdict, deque

    # Build graph and track accessible nodes
    graph = defaultdict(list)
    accessible = set()
    for u, v, w in edges:
        graph[u].append((v, w))
        accessible.add(u)
        accessible.add(v)

    # Perform BFS to find all nodes reachable from any node
    all_reachable = set()
    visited = set()
    for start in accessible:
        if start not in visited:
            queue = deque([start])
            visited.add(start)
            while queue:
                node = queue.popleft()
                all_reachable.add(node)
                for neighbor, _ in graph[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

    # Check if any node is unreachable from any other node
    for node in all_reachable:
        if node not in accessible:
            continue
        visited = set()
        queue = deque([node])
        visited.add(node)
        while queue:
            current = queue.popleft()
            for neighbor, _ in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        for other in all_reachable:
            if other not in visited:
                return -1

    # If no issues found, return 0
    return 0

def build_structure(graph_elements, connections):
    """Builds a graph structure from input elements and connections."""
    graph = {}
    for element in graph_elements:
        graph[element] = []
    for a, b in connections:
        graph[a].append(b)
    return graph

def traverse(graph):
    """Traverses the graph and returns a list of visited nodes in order."""
    visited = set()
    stack = []
    current = next(iter(graph.keys()))  # Start from the first element
    while True:
        if current not in visited:
            visited.add(current)
            stack.append(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    current = neighbor
                    break
            else:
                if not stack:
                    break
                current = stack.pop()
        else:
            if not stack:
                break
            current = stack.pop()
    return stack

def process(graph_elements, connections):
    """Main processing function to build and traverse the structure."""
    graph = build_structure(graph_elements, connections)
    path = traverse(graph)
    return path

def find_structure(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check for specific patterns or structures
    # Example: Find a diagonal pattern
    pattern_found = False
    for i in range(rows):
        for j in range(cols):
            if i + 1 < rows and j + 1 < cols and grid[i][j] == grid[i+1][j+1]:
                pattern_found = True
                break
        if pattern_found:
            break

    return "diagonal_pattern" if pattern_found else "no_pattern"

