    import sys
    import heapq
    from collections import deque

    def bellman_ford(graph, n, start):
        dist = [float('inf')] * n
        dist[start] = 0
        for _ in range(n - 1):
            for u, v, w in graph:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        # Check for negative cycles
        for u, v, w in graph:
            if dist[u] + w < dist[v]:
                return None  # Negative cycle detected
        return dist

    def dijkstra(graph, n, start):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    def find_negative_cycle(graph, n, start):
        dist = [float('inf')] * n
        dist[start] = 0
        for _ in range(n):
            for u, v, w in graph:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        return any(dist[u] + w < dist[v] for u, v, w in graph)

    def main():
        import sys
        input = sys.stdin.read
        data = input().split()
        idx = 0
        n = int(data[idx]); idx += 1
        m = int(data[idx]); idx += 1
        edges = []
        graph = [[] for _ in range(n)]
        for _ in range(m):
