            v = int(data[idx]) - 1; idx += 1
            w = int(data[idx]); idx += 1
            edges.append((u, v, w))
            graph[u].append((v, w))
        # Detect negative cycles and handle accordingly
        if find_negative_cycle(edges, n, 0):
            print(-1)
            return
        # Run Bellman-Ford from node 0
        dist = bellman_ford(edges, n, 0)
        if dist is None:
            print(-1)
            return
        if dist[n - 1] == float('inf'):
            print(-1)
        else:
            print(dist[n - 1])

