    import sys
    sys.setrecursionlimit(10000)
    import heapq

    def bellman_ford(n, edges, source, sink):
        # Build adjacency list
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))

        # Initialize distance array
        dist = [float('inf')] * n
        dist[source] = 0

        # Relax edges up to n-1 times
        for i in range(n - 1):
            updated = False
            for u in range(n):
                if dist[u] == float('inf'):
                    continue
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        updated = True
            if not updated:
                break

        # Check for negative cycles
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    # Negative cycle detected
                    return None

        # Check if sink is reachable
        if dist[sink] == float('inf'):
            return None

        # Return the minimum distance to sink
        return dist[sink]

    # Read input (simulated as per the function signature)
    n_nodes = 100  # since nodes are numbered 0 to 99
