def solve():
    def normalize(data):
        if not data:
            return ''
        result = []
        i = 0
        n = len(data)
        while i < n:
            if data[i] == '(':  # start of a group
                count = 0
                j = i + 1
                while j < n and data[j] != ')':
                    if data[j] == '[':
                        j = data.find(']', j) + 1
                    elif data[j] == '{':
                        j = data.find('}', j) + 1
                    else:
                        j += 1
                    count += 1
                if j < n and data[j] == ')':
                    group = data[i+1:j]
                    result.append(normalize(group))
                    i = j + 1
                else:
                    result.append(data[i])
                    i += 1
            elif data[i] in '[]{}':
                result.append(data[i])
                i += 1
            else:
                result.append(data[i])
                i += 1
        return ''.join(result)

    def is_valid(s):
        if not s:
            return False
        if s[0] not in '({[':
            return False
        stack = []
        for char in s:
            if char in '({[':
                stack.append(char)
            elif char in ')]}':
                if not stack:
                    return False
                if (stack[-1] == '(' and char != ')') or \
                   (stack[-1] == '[' and char != ']') or \
                   (stack[-1] == '{' and char != '}'):
                    return False
                stack.pop()
        return not stack

    def expand(s):
        if not s:
            return ''
        result = []
        i = 0
        while i < len(s):
            if s[i] == '(':
                j = i + 1
                count = 1
                while j < len(s) and count > 0:
                    if s[j] == '(':
                        count += 1
                    elif s[j] == ')':
                        count -= 1
                    j += 1
                group = s[i+1:j-1]
                expr = expand(group)
                if i > 0:
                    result.append(expr)
                i = j
            elif s[i] == ',':
                result.append('')
                i += 1
            else:
                result.append(s[i])
                i += 1
        return ''.join(result)

    return {
        'normalize': normalize,
        'is_valid': is_valid,
        'expand': expand
    }

