def find_path(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    path = []
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 'S':
                start = (r, c)
            elif matrix[r][c] == 'E':
                end = (r, c)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c, path):
        if r < 0 or c < 0 or r >= rows or c >= cols or visited[r][c]:
            return False
        visited[r][c] = True
        path.append((r, c))
        if (r, c) == end:
            return True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if matrix[nr][nc] in ['S', 'E'] or ord(matrix[nr][nc]) - ord(matrix[r][c]) <= 1:
                    if dfs(nr, nc, path):
                        return True
        path.pop()
        return False

    if dfs(start[0], start[1], path):
        return path
    return []

