            self.adj[u].append(v)
            self.adj[v].append(u)

        def dfs(self, start, visited):
            stack = [start]
            visited.add(start)
            while stack:
                node = stack.pop()
                for neighbor in self.adj[node]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)

        def count_components(self):
            visited = set()
            count = 0
            for i in range(self.n):
                if i not in visited:
                    self.dfs(i, visited)
                    count += 1
            return count

