class Solution:
    def avoidFleet(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        visited = [[False for _ in range(n)] for _ in range(m)]
        queue = []

        # Find starting positions (land)
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'L':
                    queue.append((i, j))

        # BFS to mark all reachable land
        while queue:
            x, y = queue.pop(0)
            if not visited[x][y]:
                visited[x][y] = True
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == 'L':
                        queue.append((nx, ny))

        # Count islands in water (cells with 'W' not reachable from land)
        result = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'W' and not visited[i][j]:
                    result += 1
        return result

class Solution:
    def avoid_ship(self, matrix: List[List[int]]) -> int:
        n = len(matrix)
        visited = [False] * n

        def dfs(i):
            visited[i] = True
            for j in range(n):
                if matrix[i][j] == 1 and not visited[j]:
                    dfs(j)

        for i in range(n):
            if not visited[i]:
                dfs(i)

        return sum(1 for i in range(n) if not visited[i])

class Solution:
    def avoidFleet(self, grid: List[List[str]]) -> bool:
        m, n = len(grid), len(grid[0])

        def is_valid(x, y):
            return 0 <= x < m and 0 <= y < n

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        def dfs(x, y, visited):
            if (x, y) in visited:
                return
            visited.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and grid[nx][ny] == '1' and (nx, ny) not in visited:
                    dfs(nx, ny, visited)

        visited = set()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '1' and (i, j) not in visited:
                    dfs(i, j, visited)

        return len(visited) < m * n

