class Solution:
    def canCross(self, stones: List[int]) -> bool:
        from collections import defaultdict

        dp = defaultdict(set)
        dp[0].add(0)
        for i, stone in enumerate(stones):
            for jump in dp[stone]:
                for next_jump in range(1, jump + 1):
                    if stone + next_jump in dp:
                        dp[stone + next_jump].add(next_jump)
        return stones[-1] in dp

class Solution:
    def shipWithinShips(self, weights: List[int], days: int) -> int:
        def can_deliver(capacity):
            total = 0
            ships = 1
            for weight in weights:
                if total + weight > capacity:
                    ships += 1
                    total = weight
                else:
                    total += weight
            return ships <= days

        left = max(weights)
        right = sum(weights)
        while left < right:
            mid = (left + right) // 2
            if can_deliver(mid):
                right = mid
            else:
                left = mid + 1
        return left

