def find_all_paths(start, graph, visited, path, result):
    visited.add(start)
    path.append(start)
    if len(path) == 1:
        result.append(path.copy())
    else:
        for neighbor in graph[start]:
            if neighbor not in visited:
                find_all_paths(neighbor, graph, visited, path, result)
    path.pop()
    visited.remove(start)

