#include <queue>
using namespace std;

struct Point {
    int x, y;
    Point(int x, int y) : x(x), y(y) {}
};

bool isValid(int x, int y, int rows, int cols) {
    return x >= 0 && x < rows && y >= 0 && y < cols;
}

vector<Point> findPath(const vector<vector<int>>& grid, int rows, int cols) {
    queue<vector<Point>> q;
    vector<Point> start = {0, 0};
    q.push(start);
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    visited[0][0] = true;

    while (!q.empty()) {
        vector<Point> current = q.front(); q.pop();
        int x = current.back().x;
        int y = current.back().y;

        // Check for the target (last cell)
        if (x == rows - 1 && y == cols - 1) {
            return current;
        }

        // Try moving in 4 directions
        vector<Point> directions = {{x + 1, y}, {x - 1, y}, {x, y + 1}, {x, y - 1}};
        for (auto& p : directions) {
            if (isValid(p.x, p.y, rows, cols) && !visited[p.x][p.y] && grid[p.x][p.y] == 1) {
                vector<Point> newPath = current;
                newPath.push_back(p);
                visited[p.x][p.y] = true;
                q.push(newPath);
            }
        }
    }

    return vector<Point>(); // No path found
}

