    rows = len(puzzle)
    cols = len(puzzle[0])

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or puzzle[r][c] == '#' or visited[r][c]:
            return False

        visited[r][c] = True
        if puzzle[r][c] == 'G':
            return True

        for dr, dc in directions:
            if dfs(r + dr, c + dc):
                return True

        visited[r][c] = False
        return False

    for r in range(rows):
        for c in range(cols):
            if puzzle[r][c] == 'S':
                if dfs(r, c):
                    return True
    return False

