int dir[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

struct State {
    int row;
    int col;
    int steps;
    int dir; // direction from which we came
    State(int r, int c, int s, int d) : row(r), col(c), steps(s), dir(d) {}
};

int main() {
    int n;
    cout << "Enter size of grid: ";
    cin >> n;

    vector<vector<char>> grid(n, vector<char>(n));
    cout << "Enter grid (use 0-9 for free space, 'X' for blocked):\n";
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> grid[i][j];
        }
    }

    queue<State> q;
    q.push(State(0, 0, 0, -1));

    map<pair<int, int>, int> visited;

    while (!q.empty()) {
        State curr = q.front();
        q.pop();

        pair<int, int> pos = {curr.row, curr.col};
        if (visited.find(pos) != visited.end() && visited[pos] <= curr.steps) continue;
        visited[pos] = curr.steps;

        if (curr.row == n - 1 && curr.col == n - 1) {
            cout << "Found path with " << curr.steps << " steps.\n";
            return 0;
        }

        for (int d = 0; d < 4; ++d) {
            if (d == curr.dir) continue;
            int nr = curr.row + dir[d][0];
            int nc = curr.col + dir[d][1];

            if (nr >= 0 && nr < n && nc >= 0 && nc < n && grid[nr][nc] != 'X') {
                q.push(State(nr, nc, curr.steps + 1, d));
            }
        }
    }

    cout << "No path found.\n";
    return 0;
}

