// Directions: up, right, down, left
int dir[4][2] = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

// Check if position is within bounds
bool isValid(int x, int y) {
    return x >= 0 && y >= 0 && x < MAX_SIZE && y < MAX_SIZE;
}

// BFS to find the shortest path from (sx, sy) to (ex, ey)
vector<pair<int, int>> bfs(int sx, int sy, int ex, int ey) {
    queue<pair<int, int>> q;
    q.push({sx, sy});
    visited[sx][sy] = true;
    vector<pair<int, int>> parent(MAX_SIZE * MAX_SIZE);

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        for (int i = 0; i < 4; ++i) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];

            if (isValid(nx, ny) && !visited[nx][ny] && grid[nx][ny] == ' ') {
                visited[nx][ny] = true;
                parent[nx * MAX_SIZE + ny] = {x, y};
                q.push({nx, ny});

                if (nx == ex && ny == ey) {
                    // Reconstruct the path
                    vector<pair<int, int>> path;
                    int curr = nx * MAX_SIZE + ny;
                    while (curr != sx * MAX_SIZE + sy) {
                        path.push_back({parent[curr].first, parent[curr].second});
                        curr = parent[curr].first * MAX_SIZE + parent[curr].second;
                    }
                    path.push_back({sx, sy});
                    reverse(path.begin(), path.end());
                    return path;
                }
            }
        }
    }
    return {};
}

