def avoid_man_house_and_baby(grid, man_pos, house_pos, baby_pos):
    if man_pos in [house_pos, baby_pos] or house_pos == baby_pos:
        return "Invalid positions: man, house, and baby must be distinct."

    for x in range(len(grid)):
        for y in range(len(grid[x])):
            if grid[x][y] == 'm':
                man_pos = (x, y)
            elif grid[x][y] == 'h':
                house_pos = (x, y)
            elif grid[x][y] == 'b':
                baby_pos = (x, y)

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(x, y):
        if x < 0 or y < 0 or x >= rows or y >= cols or visited[x][y]:
            return False

        if (x, y) == man_pos or (x, y) == house_pos or (x, y) == baby_pos:
            return False

        visited[x][y] = True
        return any(dfs(nx, ny) for nx, ny in [(x+1,y), (x-1,y), (x,y+1), (x,y-1)])

