def avoid_man_house_baby(grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    def is_blocked(r, c):
        return grid[r][c] in ['M', 'H', 'B']  # Avoid man, house, baby

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or visited[r][c] or is_blocked(r, c):
            return False

        visited[r][c] = True
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if dfs(nr, nc):
                return True
        visited[r][c] = False
        return False

    for r in range(rows):
        for c in range(cols):
            if not is_blocked(r, c):
                if dfs(r, c):
                    return True
    return False

