// BFS to find the shortest path
pair<int, int> bfs(int startRow, int startCol, int endRow, int endCol, int rows, int cols) {
    queue<tuple<int, int, int, int>> q;
    q.push({startRow, startCol, 0, 0});
    visited[startRow][startCol] = true;

    while (!q.empty()) {
        auto [x, y, dx, dy] = q.front();
        q.pop();

        if (x == endRow && y == endCol) {
            return {dx, dy};
        }

        int newX = x + dx;
        int newY = y + dy;

        if (isValid(newX, newY, rows, cols)) {
            visited[newX][newY] = true;
            q.push({newX, newY, dx + 1, dy});
        }

        newX = x - dx;
        newY = y - dy;

        if (isValid(newX, newY, rows, cols)) {
            visited[newX][newY] = true;
            q.push({newX, newY, dx, dy + 1});
        }
    }

    return {0, 0};
}

