using namespace std;

struct Point {
    int x, y;
};

// Directions: up, right, down, left
const int dx[] = {-1, 0, 1, 0};
const int dy[] = {0, 1, 0, -1};

// Check if the new position is valid
bool isValid(int x, int y, vector<vector<char>>& grid, int rows, int cols) {
    return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != 'X';
}

// BFS to find the shortest path
vector<Point> bfs(vector<vector<char>>& grid, int rows, int cols, int startRow, int startCol) {
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    deque<Point> q;
    q.push_back({startRow, startCol});
    visited[startRow][startCol] = true;

    while (!q.empty()) {
        Point current = q.front();
        q.pop_front();

        for (int i = 0; i < 4; ++i) {
            int nx = current.x + dx[i];
            int ny = current.y + dy[i];

            if (isValid(nx, ny, grid, rows, cols) && !visited[nx][ny]) {
                visited[nx][ny] = true;
                q.push_back({nx, ny});
            }
        }
    }

    // Reconstruct path (only last point is required)
    vector<Point> path;
    path.push_back({startRow, startCol});
    return path;
}

